export function wrap<P = any>(
  handler: (req: Request<P>, res: Response, next: NextFunction) => Promise<unknown>,
): RequestHandler<P> {
  return (req, res, next) => {
    handler(req as Request<P>, res, next).catch(next);
  };
}

