/* Changelog failure does not mask success: if appendChangeLog throws after saveLibrary, the
   response stays at the operation's normal status with its normal body, and carries a `warning`
   instead of becoming a 5xx. saveLibrary must have already been called — the write really happened.
   When changelog does not throw, the `warning` field is absent. */
describe('changelog write failure leaves write success intact', () => {
  const clError = new Error('changelog write failed');

  it.each([
    ['create', () => request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' })],
    ['update', () => request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' })],
    ['delete', () => request(appAs(true)).delete('/library/virtues/v-might')],
    ['settings', () => request(appAs(true)).put('/library/settings').send({ GlossaryAutoLink: false })],
    ['import', () => request(appAs(true)).post('/library/import').send({ library: makeLibrary(), moves: [] })],
    ['reset', () => request(appAs(true)).post('/library/reset')],
    ['restore', async () => {
      const deleteEntry = {
        Id: 'cl-1',
        At: '2026-09-11T18:00:00.000Z',
        Who: 'Mike',
        Action: 'delete' as const,
        Collection: 'virtues',
        ObjectId: 'v-resolve',
        ObjectName: 'Resolve',
        Before: { Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' },
        After: null,
      };
      vi.mocked(repo.getChangeLogEntry).mockResolvedValue(deleteEntry);
      return request(appAs(true)).post('/library/changelog/cl-1/restore');
    }],
  ])('when changelog fails on %s, response is still 200 with warning', async (_label, call) => {
    vi.mocked(repo.appendChangeLog).mockRejectedValue(clError);

    const res = await call();

    expect(res.status).toBe(200);
    expect(repo.saveLibrary).toHaveBeenCalled();
    expect(res.body.warning).toBe('changelog write failed');
    expect(repo.appendChangeLog).toHaveBeenCalled();
  });

  it.each([
    ['create', () => request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' })],
    ['update', () => request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' })],
    ['delete', () => request(appAs(true)).delete('/library/virtues/v-might')],
    ['settings', () => request(appAs(true)).put('/library/settings').send({ GlossaryAutoLink: false })],
    ['import', () => request(appAs(true)).post('/library/import').send({ library: makeLibrary(), moves: [] })],
    ['reset', () => request(appAs(true)).post('/library/reset')],
  ])('no warning field when changelog succeeds on %s', async (_label, call) => {
    const res = await call();

    expect(res.status).toBe(200);
    expect(res.body).not.toHaveProperty('warning');
  });

  it('restore has no warning field when changelog succeeds', async () => {
    const deleteEntry = {
      Id: 'cl-1',
      At: '2026-09-11T18:00:00.000Z',
      Who: 'Mike',
      Action: 'delete' as const,
      Collection: 'virtues',
      ObjectId: 'v-resolve',
      ObjectName: 'Resolve',
      Before: { Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' },
      After: null,
    };
    vi.mocked(repo.getChangeLogEntry).mockResolvedValue(deleteEntry);

    const res = await request(appAs(true)).post('/library/changelog/cl-1/restore');

    expect(res.status).toBe(200);
    expect(res.body).not.toHaveProperty('warning');
  });
});

